 simple={x:(ROOT/x).read_text() for x in r.MUTABLE if x not in {r.STATE,'MEMORY.md','方向追踪.md','全景视野.md','扩展认知.md'}};simple[r.PREFIX+'RESUME.md']=simple[r.PREFIX+'RESUME.md'].replace('revision250。','revision251（P33 source-freeze receipt repaired）。',1)
